48	
49	export type ScanStatus = "pending" | "analyzing" | "completed" | "failed";
50	
51	export type PageType =
52	  | "landing"
53	  | "product"
54	  | "homepage"
55	  | "pricing"
56	  | "signup"
57	  | "blog"
58	  | "other";
