1	/**
2	 * dodo-checkout — Edge Function
3	 *
4	 * Creates a Dodo Payments subscription checkout session for plan upgrades.
5	 *
6	 * Expected request body:
7	 *   { plan: 'pro' | 'agency'; billing_cycle: 'monthly' | 'annual' }
8	 *
9	 * Returns:
10	 *   { url: string } — Dodo-hosted checkout page URL
11	 *
12	 * Required env vars:
13	 *   DODO_API_KEY
14	 *   DODO_PRODUCT_PRO_MONTHLY
15	 *   DODO_PRODUCT_PRO_ANNUAL
16	 *   DODO_PRODUCT_AGENCY_MONTHLY
17	 *   DODO_PRODUCT_AGENCY_ANNUAL
18	 *   SITE_URL
19	 *   SUPABASE_URL
20	 *   SUPABASE_ANON_KEY
21	 *   SUPABASE_SERVICE_ROLE_KEY
22	 */
23	
24	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
25	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
26	
27	const corsHeaders = {
28	  "Access-Control-Allow-Origin": "*",
29	  "Access-Control-Allow-Headers":
30	    "authorization, x-client-info, apikey, content-type",
31	};
32	
33	function getProductId(plan: string, billingCycle: string): string | null {
34	  const map: Record<string, string> = {
35	    "starter:monthly": Deno.env.get("DODO_PRODUCT_STARTER_MONTHLY") ?? "",
36	    "starter:annual": Deno.env.get("DODO_PRODUCT_STARTER_ANNUAL") ?? "",
37	    "growth:monthly": Deno.env.get("DODO_PRODUCT_GROWTH_MONTHLY") ?? "",
38	    "growth:annual": Deno.env.get("DODO_PRODUCT_GROWTH_ANNUAL") ?? "",
39	    "pro:monthly": Deno.env.get("DODO_PRODUCT_PRO_MONTHLY") ?? "",
40	    "pro:annual": Deno.env.get("DODO_PRODUCT_PRO_ANNUAL") ?? "",
41	    "agency:monthly": Deno.env.get("DODO_PRODUCT_AGENCY_MONTHLY") ?? "",
42	    "agency:annual": Deno.env.get("DODO_PRODUCT_AGENCY_ANNUAL") ?? "",
43	  };
44	  return map[`${plan}:${billingCycle}`] || null;
45	}
46	
47	serve(async (req: Request) => {
48	  if (req.method === "OPTIONS") {
49	    return new Response("ok", { headers: corsHeaders });
50	  }
51	
52	  try {
53	    // ── 1. Auth ──────────────────────────────────────────────────────
54	    const authHeader = req.headers.get("Authorization");
55	    if (!authHeader) {
56	      return new Response(
57	        JSON.stringify({ error: "Missing Authorization header" }),
58	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
59	      );
60	    }
61	
62	    const supabaseUser = createClient(
63	      Deno.env.get("SUPABASE_URL") ?? "",
64	      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
65	      { global: { headers: { Authorization: authHeader } } }
66	    );
67	
68	    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
69	    if (userError || !user) {
70	      return new Response(
71	        JSON.stringify({ error: "Unauthorized" }),
72	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
73	      );
74	    }
75	
76	    // ── 2. Parse + validate body ─────────────────────────────────────
77	    let body: { plan?: string; billing_cycle?: string };
78	    try {
79	      body = await req.json();
80	    } catch {
81	      return new Response(
82	        JSON.stringify({ error: "Invalid JSON body" }),
83	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
84	      );
85	    }
86	
87	    const { plan, billing_cycle } = body;
88	
89	    if (!plan || !["starter", "growth", "pro", "agency"].includes(plan)) {
90	      return new Response(
91	        JSON.stringify({ error: "Invalid plan. Must be 'starter', 'growth', 'pro', or 'agency'." }),
92	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
93	      );
94	    }
95	
96	    if (!billing_cycle || !["monthly", "annual"].includes(billing_cycle)) {
97	      return new Response(
98	        JSON.stringify({ error: "Invalid billing_cycle. Must be 'monthly' or 'annual'." }),
99	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
100	      );
101	    }
102	
103	    const productId = getProductId(plan, billing_cycle);
104	    if (!productId) {
105	      console.error(`Missing product ID for ${plan}:${billing_cycle}`);
106	      return new Response(
107	        JSON.stringify({ error: "Pricing configuration error. Contact support." }),
108	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
109	      );
110	    }
111	
112	    // ── 3. Get user profile ──────────────────────────────────────────
113	    const supabaseAdmin = createClient(
114	      Deno.env.get("SUPABASE_URL") ?? "",
115	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
116	    );
117	
118	    const { data: profile, error: profileError } = await supabaseAdmin
119	      .from("profiles")
120	      .select("id, email, full_name, dodo_customer_id")
121	      .eq("id", user.id)
122	      .single();
123	
124	    if (profileError || !profile) {
125	      console.error("Profile fetch error:", profileError);
126	      return new Response(
127	        JSON.stringify({ error: "User profile not found." }),
128	        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
129	      );
130	    }
131	
132	    // ── 4. Build Dodo customer payload ───────────────────────────────
133	    const customerPayload = profile.dodo_customer_id
134	      ? { create_new_customer: false, customer_id: profile.dodo_customer_id }
135	      : {
136	          create_new_customer: true,
137	          email: profile.email ?? user.email,
138	          name: profile.full_name ?? "",
139	        };
140	
141	    const origin = Deno.env.get("SITE_URL") ?? "http://localhost:5173";
142	    const dodoApiKey = Deno.env.get("DODO_API_KEY") ?? "";
143	
144	    // ── 5. Create subscription checkout with payment link ────────────
145	    const dodoRes = await fetch("https://api.dodopayments.com/subscriptions", {
146	      method: "POST",
147	      headers: {
148	        "Authorization": `Bearer ${dodoApiKey}`,
149	        "Content-Type": "application/json",
150	      },
151	      body: JSON.stringify({
152	        billing: {
153	          currency: "USD",
154	          interval: billing_cycle === "annual" ? "year" : "month",
155	          interval_count: 1,
156	        },
157	        customer: customerPayload,
158	        product_id: productId,
159	        payment_link: true,
160	        return_url: `${origin}/dashboard?checkout=success`,
161	        metadata: {
162	          user_id: user.id,
163	          plan,
164	        },
165	      }),
166	    });
167	
168	    if (!dodoRes.ok) {
169	      const errText = await dodoRes.text();
170	      console.error("Dodo API error:", dodoRes.status, errText);
171	      return new Response(
172	        JSON.stringify({ error: "Failed to create checkout session." }),
173	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
174	      );
175	    }
176	
177	    const dodoData = await dodoRes.json();
178	
179	    // Persist customer ID if newly created
180	    if (!profile.dodo_customer_id && dodoData.customer_id) {
181	      const { error: updateError } = await supabaseAdmin
182	        .from("profiles")
183	        .update({ dodo_customer_id: dodoData.customer_id })
184	        .eq("id", user.id);
185	
186	      if (updateError) {
187	        // Non-fatal — will be captured via webhook
188	        console.error("Failed to persist dodo_customer_id:", updateError);
189	      }
190	    }
191	
192	    const checkoutUrl = dodoData.payment_link;
193	    if (!checkoutUrl) {
194	      console.error("No payment_link in Dodo response:", dodoData);
195	      return new Response(
196	        JSON.stringify({ error: "No checkout URL returned from payment provider." }),
197	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
198	      );
199	    }
200	
201	    return new Response(
202	      JSON.stringify({ url: checkoutUrl }),
203	      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
204	    );
205	  } catch (error: unknown) {
206	    const message = error instanceof Error ? error.message : "Internal server error";
207	    console.error("dodo-checkout error:", error);
208	    return new Response(
209	      JSON.stringify({ error: message }),
210	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
211	    );
212	  }
213	});
