/**
 * api-v1 — REST API Gateway (Edge Function)
 *
 * Accepts POST requests authenticated with a ConvertScan API key.
 * API keys are prefixed `cs_live_` and validated via SHA-256 hash lookup.
 *
 * Auth: Authorization: Bearer cs_live_xxxxxxxxxxxx
 *
 * Actions:
 *   create_scan  — { action, url, page_type }
 *   get_scan     — { action, scan_id }
 *   list_scans   — { action, page?, limit? }
 *   get_report   — { action, scan_id }
 *
 * Required env vars:
 *   SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── CORS headers ──────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

function errorResponse(message: string, status: number): Response {
  return jsonResponse({ error: message }, status);
}

// ── SHA-256 hash helper ───────────────────────────────────────

async function sha256Hex(input: string): Promise<string> {
  const encoded = new TextEncoder().encode(input);
  const hashBuffer = await crypto.subtle.digest("SHA-256", encoded);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
}

// ── Typed request body ────────────────────────────────────────

type PageType = "landing" | "product" | "homepage" | "pricing" | "signup" | "blog" | "other";

interface CreateScanBody {
  action: "create_scan";
  url: string;
  page_type?: PageType;
}

interface GetScanBody {
  action: "get_scan";
  scan_id: string;
}

interface ListScansBody {
  action: "list_scans";
  page?: number;
  limit?: number;
}

interface GetReportBody {
  action: "get_report";
  scan_id: string;
}

type RequestBody = CreateScanBody | GetScanBody | ListScansBody | GetReportBody;

// ── Main handler ──────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return errorResponse("Method not allowed. Use POST.", 405);
  }

  try {
    // ── 1. Extract API key from Authorization header ──────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return errorResponse(
        "Missing or invalid Authorization header. Expected: Bearer cs_live_...",
        401,
      );
    }

    const apiKey = authHeader.slice(7).trim();
    if (!apiKey.startsWith("cs_live_")) {
      return errorResponse("Invalid API key format.", 401);
    }

    // ── 2. Hash the key and look it up ────────────────────────────
    const keyHash = await sha256Hex(apiKey);

    const supabaseAdmin = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
    );

    const { data: apiKeyRow, error: keyError } = await supabaseAdmin
      .from("api_keys")
      .select("id, user_id, permissions, rate_limit")
      .eq("key_hash", keyHash)
      .is("revoked_at", null)
      .single();

    if (keyError || !apiKeyRow) {
      return errorResponse("Invalid or revoked API key.", 401);
    }

    // ── 3. Update last_used_at (fire-and-forget) ──────────────────
    supabaseAdmin
      .from("api_keys")
      .update({ last_used_at: new Date().toISOString() })
      .eq("id", apiKeyRow.id)
      .then(() => {/* intentionally background */});

    const userId: string = apiKeyRow.user_id;

    // ── 4. Parse request body ─────────────────────────────────────
    let body: RequestBody;
    try {
      body = await req.json() as RequestBody;
    } catch {
      return errorResponse("Invalid JSON body.", 400);
    }

    if (!body || typeof body.action !== "string") {
      return errorResponse("Missing required field: action.", 400);
    }

    // ── 5. Route to action handler ────────────────────────────────
    switch (body.action) {
      case "create_scan":
        return await handleCreateScan(body, userId, supabaseAdmin, req);

      case "get_scan":
        return await handleGetScan(body, userId, supabaseAdmin);

      case "list_scans":
        return await handleListScans(body, userId, supabaseAdmin);

      case "get_report":
        return await handleGetReport(body, userId, supabaseAdmin);

      default:
        return errorResponse(
          `Unknown action. Valid actions: create_scan, get_scan, list_scans, get_report.`,
          400,
        );
    }
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "Internal server error";
    console.error("api-v1 error:", err);
    return errorResponse(message, 500);
  }
});

// ── Action: create_scan ───────────────────────────────────────

async function handleCreateScan(
  body: CreateScanBody,
  userId: string,
  supabase: ReturnType<typeof createClient>,
  req: Request,
): Promise<Response> {
  if (!body.url || typeof body.url !== "string") {
    return errorResponse("Missing required field: url.", 400);
  }

  // Validate URL format
  try {
    new URL(body.url);
  } catch {
    return errorResponse("Invalid URL format.", 400);
  }

  const pageType: PageType = body.page_type ?? "other";
  const validPageTypes: PageType[] = ["landing", "product", "homepage", "pricing", "signup", "blog", "other"];
  if (!validPageTypes.includes(pageType)) {
    return errorResponse(
      `Invalid page_type. Valid values: ${validPageTypes.join(", ")}.`,
      400,
    );
  }

  // Check scan limit for user
  const { data: profile } = await supabase
    .from("profiles")
    .select("scans_used, scan_limit, plan")
    .eq("id", userId)
    .single();

  if (profile && profile.scans_used >= profile.scan_limit) {
    return errorResponse(
      `Scan limit reached (${profile.scans_used}/${profile.scan_limit}). Upgrade your plan to run more scans.`,
      429,
    );
  }

  // Insert scan row
  const { data: scan, error: scanError } = await supabase
    .from("scans")
    .insert({
      user_id: userId,
      url: body.url,
      page_type: pageType,
      status: "analyzing",
    })
    .select("id, url, page_type, status, created_at")
    .single();

  if (scanError || !scan) {
    console.error("Failed to create scan:", scanError);
    return errorResponse("Failed to create scan.", 500);
  }

  // Invoke analyze-url function asynchronously (best-effort)
  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

  // Fire-and-forget: invoke the analyze-url function
  fetch(`${supabaseUrl}/functions/v1/analyze-url`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${serviceKey}`,
      "Content-Type": "application/json",
      // Pass service key as auth so analyze-url can validate
      "x-client-info": "api-v1-gateway",
    },
    body: JSON.stringify({
      scan_id: scan.id,
      url: body.url,
      page_type: pageType,
      user_id: userId,
    }),
  }).catch((err: unknown) => {
    console.warn("analyze-url invocation failed (async):", err);
  });

  return jsonResponse({
    scan_id: scan.id,
    status: "analyzing",
    url: scan.url,
    page_type: scan.page_type,
    created_at: scan.created_at,
  }, 202);
}

// ── Action: get_scan ──────────────────────────────────────────

async function handleGetScan(
  body: GetScanBody,
  userId: string,
  supabase: ReturnType<typeof createClient>,
): Promise<Response> {
  if (!body.scan_id || typeof body.scan_id !== "string") {
    return errorResponse("Missing required field: scan_id.", 400);
  }

  const { data: scan, error } = await supabase
    .from("scans")
    .select("*")
    .eq("id", body.scan_id)
    .eq("user_id", userId)
    .single();

  if (error || !scan) {
    return errorResponse("Scan not found.", 404);
  }

  const { data: results } = await supabase
    .from("scan_results")
    .select("pillar, score, weight, benchmark, findings")
    .eq("scan_id", body.scan_id);

  return jsonResponse({ scan, results: results ?? [] });
}

// ── Action: list_scans ────────────────────────────────────────

async function handleListScans(
  body: ListScansBody,
  userId: string,
  supabase: ReturnType<typeof createClient>,
): Promise<Response> {
  const page = Math.max(1, body.page ?? 1);
  const limit = Math.min(50, Math.max(1, body.limit ?? 20));
  const offset = (page - 1) * limit;

  const { data: scans, error, count } = await supabase
    .from("scans")
    .select(
      "id, url, page_type, status, overall_score, issues_found, created_at, completed_at",
      { count: "exact" },
    )
    .eq("user_id", userId)
    .order("created_at", { ascending: false })
    .range(offset, offset + limit - 1);

  if (error) {
    console.error("list_scans error:", error);
    return errorResponse("Failed to fetch scans.", 500);
  }

  return jsonResponse({
    scans: scans ?? [],
    pagination: {
      page,
      limit,
      total: count ?? 0,
      total_pages: Math.ceil((count ?? 0) / limit),
    },
  });
}

// ── Action: get_report ────────────────────────────────────────

async function handleGetReport(
  body: GetReportBody,
  userId: string,
  supabase: ReturnType<typeof createClient>,
): Promise<Response> {
  if (!body.scan_id || typeof body.scan_id !== "string") {
    return errorResponse("Missing required field: scan_id.", 400);
  }

  const { data: scan, error: scanError } = await supabase
    .from("scans")
    .select("*")
    .eq("id", body.scan_id)
    .eq("user_id", userId)
    .single();

  if (scanError || !scan) {
    return errorResponse("Scan not found.", 404);
  }

  const [{ data: results }, { data: rewrites }] = await Promise.all([
    supabase
      .from("scan_results")
      .select("*")
      .eq("scan_id", body.scan_id),
    supabase
      .from("copy_rewrites")
      .select("element_type, original, suggested, reasoning, impact")
      .eq("scan_id", body.scan_id),
  ]);

  return jsonResponse({
    scan,
    pillar_results: results ?? [],
    copy_rewrites: rewrites ?? [],
  });
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { ApiKey } from "@/types";

// ── SHA-256 helper (same algorithm as edge function) ──────────

async function hashApiKey(key: string): Promise<string> {
  const encoded = new TextEncoder().encode(key);
  const hashBuffer = await crypto.subtle.digest("SHA-256", encoded);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
}

// ── useApiKeys ────────────────────────────────────────────────
// Fetches active (non-revoked) API keys for the current user.

export function useApiKeys() {
  const { user } = useAuth();

  return useQuery<ApiKey[]>({
    queryKey: ["api-keys", user?.id],
    queryFn: async () => {
      if (!user) return [];

      const { data, error } = await supabase
        .from("api_keys")
        .select(
          "id, user_id, team_id, name, key_prefix, permissions, rate_limit, last_used_at, created_at, revoked_at",
        )
        .eq("user_id", user.id)
        .is("revoked_at", null)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data ?? []) as ApiKey[];
    },
    enabled: !!user,
  });
}

// ── useCreateApiKey ───────────────────────────────────────────
// Generates a new API key, hashes it, stores the hash, and returns
// the FULL key (shown only once — never stored in plaintext).

export interface CreatedApiKey {
  fullKey: string;
  row: ApiKey;
}

export function useCreateApiKey() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation<CreatedApiKey, Error, { name: string }>({
    mutationFn: async ({ name }) => {
      if (!user) throw new Error("Not authenticated");

      // Generate key: cs_live_ + 32 hex chars from UUID (no dashes = 32 chars)
      const rawUuid = crypto.randomUUID().replace(/-/g, "");
      const fullKey = `cs_live_${rawUuid}`;
      const keyPrefix = fullKey.slice(0, 12);

      const keyHash = await hashApiKey(fullKey);

      const { data, error } = await supabase
        .from("api_keys")
        .insert({
          user_id: user.id,
          name,
          key_hash: keyHash,
          key_prefix: keyPrefix,
          permissions: ["read", "write"],
        })
        .select(
          "id, user_id, team_id, name, key_prefix, permissions, rate_limit, last_used_at, created_at, revoked_at",
        )
        .single();

      if (error) throw new Error(error.message);
      if (!data) throw new Error("Failed to create API key.");

      return { fullKey, row: data as ApiKey };
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["api-keys"] });
    },
    onError: (error) => {
      toast.error(error.message || "Failed to create API key.");
    },
  });
}

// ── useRevokeApiKey ───────────────────────────────────────────
// Sets revoked_at = NOW() on the given key row.

export function useRevokeApiKey() {
  const queryClient = useQueryClient();

  return useMutation<void, Error, { id: string }>({
    mutationFn: async ({ id }) => {
      const { error } = await supabase
        .from("api_keys")
        .update({ revoked_at: new Date().toISOString() })
        .eq("id", id);

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["api-keys"] });
      toast.success("API key revoked.");
    },
    onError: (error) => {
      toast.error(error.message || "Failed to revoke API key.");
    },
  });
}

import { useState } from "react";
import { Copy, Check, AlertTriangle, Loader2 } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useCreateApiKey } from "@/hooks/use-api-keys";

interface ApiKeyDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function ApiKeyDialog({ open, onOpenChange }: ApiKeyDialogProps) {
  const [name, setName] = useState("My API Key");
  const [generatedKey, setGeneratedKey] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const { mutate: createApiKey, isPending } = useCreateApiKey();

  function handleGenerate() {
    createApiKey(
      { name: name.trim() || "My API Key" },
      {
        onSuccess: ({ fullKey }) => {
          setGeneratedKey(fullKey);
        },
      },
    );
  }

  async function handleCopy() {
    if (!generatedKey) return;
    await navigator.clipboard.writeText(generatedKey);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  function handleClose() {
    setName("My API Key");
    setGeneratedKey(null);
    setCopied(false);
    onOpenChange(false);
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Create API Key</DialogTitle>
          <DialogDescription>
            Generate a new API key for programmatic access to ConvertScan.
          </DialogDescription>
        </DialogHeader>

        {!generatedKey ? (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="key-name">Key Name</Label>
              <Input
                id="key-name"
                placeholder="e.g. Production, CI/CD, My App"
                value={name}
                onChange={(e) => setName(e.target.value)}
                disabled={isPending}
                maxLength={64}
              />
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex items-start gap-2 rounded-lg border border-amber-200 bg-amber-50 p-3">
              <AlertTriangle className="h-4 w-4 shrink-0 text-amber-600 mt-0.5" />
              <p className="text-sm text-amber-800">
                Save this key now — it will not be shown again.
              </p>
            </div>

            <div className="space-y-2">
              <Label>Your API Key</Label>
              <div className="flex gap-2">
                <code className="flex-1 overflow-auto rounded-md border bg-muted px-3 py-2 font-mono text-sm break-all">
                  {generatedKey}
                </code>
                <Button
                  type="button"
                  variant="outline"
                  size="icon"
                  onClick={handleCopy}
                  aria-label="Copy API key"
                >
                  {copied ? (
                    <Check className="h-4 w-4 text-green-600" />
                  ) : (
                    <Copy className="h-4 w-4" />
                  )}
                </Button>
              </div>
            </div>
          </div>
        )}

        <DialogFooter>
          {!generatedKey ? (
            <>
              <Button variant="outline" onClick={handleClose} disabled={isPending}>
                Cancel
              </Button>
              <Button onClick={handleGenerate} disabled={isPending || !name.trim()}>
                {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Generate Key
              </Button>
            </>
          ) : (
            <Button onClick={handleClose} className="w-full">
              Done
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

