                  <KeyRow key={key.id} apiKey={key} />
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </PremiumLock>

      {/* Documentation section */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">API Reference</CardTitle>
          <CardDescription>
            Endpoint documentation with examples for all supported actions.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <ApiDocumentation />
        </CardContent>
      </Card>

      <ApiKeyDialog open={dialogOpen} onOpenChange={setDialogOpen} />
    </div>
  );
}

